-- Fiche Les animaux (CE1) - anglais, notion 'en_animaux'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce1', 'english', 'Les animaux', $fiche$
[titre]a ou an ?[/titre]
[cadre][b]a[/b] devant une consonne : a cat, a dog, a pig
[b]an[/b] devant une voyelle : an elephant, an owl[/cadre]
[cadre=astuce]Au pluriel, on ajoute [b]s[/b] : two cat[b][color=#C62828]s[/color][/b]. Mais certains ne changent pas : two [b]fish[/b], two [b]sheep[/b].[/cadre]
